with not_flagged as (select s.* from accounts s where not exists (select 1 from transactions ch where ch.account_id = s.id and ch.merchant in ('Shell', 'Lazada'))) select account_type, case when balance >= 72000 then 'PREMIUM' else 'STANDARD' end as balance_tier, count(case when status = 'FROZEN' then 1 end) as frozen_count, count_if(account_type = 'SAVINGS') as savings_events from not_flagged group by account_type, case when balance >= 72000 then 'PREMIUM' else 'STANDARD' end having count_if(account_type = 'SAVINGS') > 1 order by frozen_count nulls first;
